import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen2Test {

    @Test
    public void testEncodeBase64String_WithStandardInput() {
        // Test with a standard byte array
        byte[] input = "Hello World".getBytes();
        // "Hello World" in Base64 is "SGVsbG8gV29ybGQ="
        String expected = "SGVsbG8gV29ybGQ=";
        String actual = Base64.encodeBase64String(input);
        assertEquals("The Base64 encoded string should match the expected value.", expected, actual);
    }








}

